// The day's affirmation in Serbian (Cyrillic), for the country pages in Serbian (Cyrillic). Written by scripts/home_extras.py from data/affirmations-i18n/; do not edit.
(function(){var D=document;if(D.getElementById("affirmations-local"))return;var e=D.createElement("script");e.type="application/json";e.id="affirmations-local";e.textContent="[\"Не мораш данас све да урадиш. Довољна је следећа мала ствар.\", \"Умор није неуспех. Уморна си зато што си ту, из дана у дан.\", \"Судови могу да сачекају. Смеш да седнеш на пет минута.\", \"Пахуљице за вечеру се такође рачунају као храњење породице.\", \"Одмор не мораш да заслужиш. Смеш да се одмориш одмах сада.\", \"Некад је победа то што су сви стигли до времена за спавање. То је права победа.\", \"Радиш више него што ико види. Ја то видим.\", \"Неуредна кућа и вољена деца. То је добра размена.\", \"У тешком дану твоје најбоље изгледа другачије, и свеједно се рачуна.\", \"Један дубок удах. Спусти рамена. Добро ти иде.\", \"У реду је данас спустити лествицу. Неког другог дана можеш опет да је подигнеш.\", \"Тражити помоћ је знак снаге, а не слабости.\", \"Смеш да кажеш не још једној обавези.\", \"Ако си се данас осећала усамљено, ниси једина мама која се тако осећала. Има нас много.\", \"Заслужујеш пријатељицу која те пита како си и сачека одговор.\", \"У реду је да се прва јавиш. Већина мама се нада да ће то неко урадити.\", \"То што се осећаш невидљиво не значи да ниси важна. Веома си важна.\", \"Твоја осећања имају смисла. Ниси „превише“.\", \"Овде не мораш да објашњаваш свој тежак дан. Разумемо.\", \"Порука другој мами која каже „и ја“ може да преокрене цео дан.\", \"Храњење, пресвлачење, љуљање, па испочетка. То је прави посао, чак и кад изгледа као седење у месту.\", \"Ти и твоја беба се још упознајете. Нема журбе.\", \"Дани с новорођенчетом су дуги. Овај период неће трајати заувек.\", \"Ако си данас само одржала малог човека ситим и на топлом, обавила си велики посао.\", \"Не мораш брзо да се вратиш у старо стање. Можеш једноставно да будеш ту где јеси.\", \"Како год да храниш своју бебу, бринеш о њој. То је оно што се рачуна.\", \"Можеш да будеш неиспавана и пуна љубави у исто време.\", \"Држи бебу и пусти кућу. Кућа ће и даље бити ту.\", \"Напад беса у продавници не чини те лошом мамом. Значи само да имаш мало дете.\", \"Малишани тестирају границе јер се уз тебе осећају сигурно.\", \"Данас си остала мирна минут дуже него јуче. То се рачуна.\", \"Ако си планула, загрљај и „извини“ поправе много тога. И науче их нечему добром.\", \"Лепљиве ручице, гласни гласови, велика осећања. Подижеш целог човека.\", \"Пето „зашто?“ у једном сату значи да мали ум расте.\", \"Не треба ти савршен дан да створиш срећну успомену.\", \"Залупљена врата нису крај приче. Остави светло упаљено.\", \"Твој тинејџер то можда не говори, али твоје стално присуство је важно.\", \"Бити она смирена у кући је тежак посао. И ти га обављаш.\", \"Неки од најбољих разговора десе се у колима. Само ти вози даље.\", \"Удаљавају се да би одрасли, а не да би те оставили за собом.\", \"Не мораш да имаш све одговоре. Слушање је велики део тога.\", \"Великој деци си и даље потребна, само на тиши начин.\", \"Све изнети сама тражи снагу коју већина људи никад не види.\", \"Довољно си добра мама за своје дете. Увек си била.\", \"Један пар руку, сто послова. Буди блага према себи.\", \"Твоја деца, гледајући тебе, уче како изгледа снажна особа пуна љубави.\", \"Одмор није напуштање дужности. Тако издржиш даље.\", \"Нико не броји поене. Важни су љубав и то што си ту.\", \"Туга и љубав извиру из истог места. Колико ти неко недостаје, показује колико си волела.\", \"Не постоји прави рок за туговање. Узми онолико времена колико ти треба.\", \"На тешке годишњице буди нежна према себи као што би била према пријатељици.\", \"Можеш да носиш тугу и свеједно да се смејеш са својом децом. Обоје је стварно.\", \"Ако си изгубила трудноћу или бебу, тај губитак је стваран, као и твоја љубав.\", \"Неким данима је туга тиха, а неким гласна. Обоје је у реду.\", \"Мањак новца не значи мањак љубави.\", \"Твоја деца ће памтити време с тобом више него ствари које си купила.\", \"Питати за помоћ око рачуна је паметно, а не срамотно. Управо за то та помоћ и постоји.\", \"Бесплатно поподне у парку може бити најлепши дан у недељи.\", \"Развукла си новац још недељу дана. За то треба право умеће.\", \"Брига око новца исцрпљује. Носиш много, и још си ту.\", \"Данас си попила чашу воде. Крени од тога.\", \"Сви су изашли из куће. Можда се ципеле нису слагале. Свеједно победа.\", \"Обавила си онај позив ког си се плашила. То је било храбро.\", \"Данас си се смејала. Задржи то.\", \"Топао оброк, чиста мајица, прича за лаку ноћ. Од малих ствари састоји се детињство.\", \"Данас си била добра према некоме, макар и само према себи.\", \"Напредак, не савршенство. Данас си се померила напред.\", \"Завршила си једну ствар са списка. То је једна више него ниједна.\", \"Добра си мама. То што бринеш око тога показује колико ти је стало.\", \"Вредиш више од онога што стигнеш да урадиш за један дан.\", \"Твојој деци не треба савршена мама. Потребна си им ти, и имају те.\", \"Буди стрпљива према себи као што си према својој деци.\", \"Смеш да заузимаш простор, да нешто желиш и да имаш своје снове.\", \"Грешка не поништава љубав. Сутра је нови почетак.\", \"Некоме си цео свет, а и даље си своја особа.\", \"У реду је не уживати у сваком минуту. И даље можеш да волиш своју децу целим срцем.\", \"Не постоји само један прави начин да будеш мама. Твој начин је у реду.\", \"Као у положају дрвета, у реду је заљуљати се. Равнотежу ћеш опет пронаћи.\", \"Чврсто постави стопала као у положају планине. Стабилнија си него што се осећаш.\", \"Ратник два: снажне ноге, раширене руке. То си ти, спремна за ову недељу.\", \"Удахни на четири, издахни на четири. Ту си, и добро ти иде.\", \"Рашири се као звезда. Смеш да заузимаш простор.\", \"Широк и низак чучањ је тешко задржати. Дуг дан такође. И ти га држиш.\", \"Можеш да се нагнеш као полумесец и и даље да стојиш.\", \"Још не мораш да дохватиш прсте на ногама. Свако мало истезања се рачуна.\", \"Положај троугла: једна рука доле, једна горе. Остани приземљена и настави да се истежеш.\", \"Касно је. Оно што данас није урађено може да сачека до сутра.\", \"Будна с бебом у ово доба? Много мама је будно с тобом управо сада.\", \"Кућа је тиха. Овај тренутак је твој. Диши.\", \"Изгурала си данашњи дан. Само је то данас требало.\", \"Ако ти мисли ноћас не дају мира, запиши их и нека сачекају до јутра.\", \"Одмори очи. Сутра можеш да кренеш испочетка.\", \"Празници могу бити тешки колико и срећни. Како год да се осећаш у ово доба године, у реду је.\", \"Сто не мора бити савршен. Важни су људи око њега.\", \"Ако ти ове године неко недостаје за столом, буди нежна према свом срцу.\", \"Хвала ти, мама, за сваки оброк, сваку вожњу и сваки загрљај.\", \"Не мораш да угостиш све, да печеш колаче нити да се смешиш све време. Једноставан празник је и даље празник.\", \"Најлепши поклон који твоја деца ове године добијају је време с тобом.\", \"И мали празник је пун љубави. Не треба много новца да буде посебан.\", \"Хладни дани, топли загрљаји. Ти си топло место у свом дому.\", \"У реду је прескочити део празничне гужве. И мир је поклон.\", \"Ако ти је ово доба ове године тешко, ниси сама. Дан по дан.\"]";D.body.appendChild(e)})();
